var import_obsidian17 = require("obsidian");

// src/utils/whatsNew.ts
var HERO_IMAGE_URL = "https://raw.githubusercontent.com/chrisurf/obsidian-voice/main/assets/hero.png";
var BUY_ME_A_COFFEE_URL = "https://www.buymeacoffee.com/chrisurf";
var BUY_ME_A_COFFEE_IMAGE_URL = "https://raw.githubusercontent.com/chrisurf/obsidian-voice/main/assets/buymeacoffee.png";
var WHATS_NEW = `## \u{1F195} New: bring any OpenAI-compatible server

Voice now talks to **any server that speaks OpenAI's speech API** \u2014 hosted routers like **OpenRouter**, gateways like **LiteLLM**, or a **self-hosted** engine such as **Kokoro** running on your own machine.

- \u{1F50C} Choose **OpenAI-compatible** in **Settings \u2192 Voice**, enter the **server URL** (and an API key if it needs one), then press **Test Credentials**.
- \u{1F4CB} Voice **loads the server's models and voices** for you \u2014 and you can **add your own** if the server doesn't list them.
- \u{1F3A7} Pick **MP3** or **WAV** \u2014 WAV files are saved and listed as chapters just like MP3s.
- \u{1F4F1} On a phone, \`localhost\` means the phone itself \u2014 use an address the phone can reach.

## MiniMax \u2014 text-to-speech that works from China \u2014 text-to-speech that works from China

Voice's **sixth provider** is here: **MiniMax**. It's a great fit for **Chinese-language** notes \u2014 and, crucially, it's reachable from **mainland China**, where the other engines often aren't.

- \u{1F30F} **Choose your region** \u2014 **global** or **mainland China** \u2014 so the API works wherever your account lives.
- \u{1F5E3}\uFE0F **Natural, multilingual voices** with especially strong Chinese support (Speech 02 HD/Turbo \xB7 Speech 01 HD/Turbo).
- \u{1F511} Set it up in **Settings \u2192 Voice \u2192 MiniMax**: pick a region and model, paste your **API key** and **Group ID**, then press **Test Credentials**.

Everything else \u2014 chapters, speed, downloads, the content toggles \u2014 works exactly like the other providers.

## \u25B6\uFE0F One play button, less clutter

Playback is simpler now \u2014 the play button does everything, so the separate Regenerate button is gone. Open the Voice player (the audio-waveform ribbon icon) and use the big play button:

- **Tap** \u25B6\uFE0F to play, pause, or cancel a generation that is in progress.
- **Press and hold** to regenerate the current note from scratch \u2014 always with your current voice and settings. A ring fills around the button as you hold.

And new **quick toggles** sit right in the player \u2014 flip **Read code blocks** (\`</>\`), **Spell out acronyms** (\`Aa\`), **Skip website URLs** (\u{1F517}), and **Embed MP3 in note** (\u{1F4CE}) with one click. The settings tab is leaner now, because the things you change while listening live in the player.

## \u{1F4C1} Save audio where you want

The save button (the download arrow) now has two simple gestures, and you can pick a **default folder** so every save lands in the same place.

- \u{1F446} **Tap** to save now \u2014 next to your note, or in your default folder if you've set one.
- \u270B **Press and hold** the save button (or right-click on desktop) to open the folder picker. In the player you can also just click the new **folder button** (\u{1F4C2}) to **save to a custom folder** in one click.
- \u{1F4CC} In the picker, **pin** a folder to make it your default (only one at a time; tap the pin again to clear it). \u2B50 **Star** folders for quick access, or type to create a new folder.
- \u{1F500} Picking a folder **saves** new audio there, or **moves** an already-saved recording (a chapter) into it \u2014 no duplicates. If a file with the same name exists, you can **Replace**, **Save as new**, or **Cancel**.
- \u{1F4BE} When a default folder is set, the save button shows a **floppy-disk** icon so you can tell at a glance where a tap will save.
- \u{1F5C2}\uFE0F Manage a saved track from its **\u22EE** menu in the player: **Move** it to another folder, **Rename** it, or **Delete** it (with a quick confirmation).

## \u{1F50A} The Voice player

Voice has a full **audiobook-style player** in the right sidebar (next to Backlinks and Outline) \u2014 always one click away.

- **Play your notes like chapters** \u2014 every MP3 in a folder becomes a numbered chapter you can play, skip, and repeat.
- **Browse audio across your vault** with the folder picker.
- **Switch provider & voice** right in the player.

Every control is one button; a few do double duty \u2014 **tap** vs. **press & hold** (a ring fills while you hold). Toggles that light up when on: \`</>\` **code** \xB7 \`Aa\` **acronyms** \xB7 \u{1F517} **skip URLs** \xB7 \u{1F4CE} **embed**.

## \u2728 Everything at a glance

**Six providers, your pick** \u2014 bring the engine you already use; every feature works identically on all of them: AWS Polly \xB7 ElevenLabs \xB7 OpenAI \xB7 Google Cloud \xB7 Azure Speech \xB7 **MiniMax**.

**Player & playback** \u2014 chapters, scrubber, speed (0.5\xD7\u20132.0\xD7), and repeat modes (off / one / all), plus configurable rewind & fast-forward (1\u201360 s). Switch provider, voice, and the content toggles without leaving the player \u2014 with live feedback while a note synthesizes.

**Your audio** \u2014 save MP3s next to the note or in a **default folder**, optionally **auto-save** and **embed** them, and **move / rename / delete** saved chapters from the player.

**Reads it your way** \u2014 toggle **read code blocks**, **spell out acronyms**, and **skip website URLs**, all from the player.

Open the player from the **audio-waveform ribbon icon**, the **"Open the player."** command, or the button below.`;
function shouldShowWhatsNew(currentVersion, lastSeenVersion) {
  return currentVersion !== "" && currentVersion !== lastSeenVersion;
}

// src/ui/WhatsNewModal.ts
var WhatsNewModal = class extends import_obsidian17.Modal {
  constructor(app, version, component, onOpenPlayer) {
    super(app);
    this.version = version;
    this.component = component;
    this.onOpenPlayer = onOpenPlayer;
  }
  onOpen() {
    const { contentEl, titleEl, modalEl } = this;
    modalEl.addClass("voice-whats-new-modal");
    titleEl.setText(`What's new in Voice ${this.version}`);
    const hero = contentEl.createEl("img", {
      cls: "voice-whats-new-hero",
      attr: { alt: "Obsidian Voice", src: HERO_IMAGE_URL }
    });
    hero.addEventListener("error", () => hero.hide());
    const support = contentEl.createDiv({ cls: "voice-whats-new-support" });
    const coffeeLink = support.createEl("a", {
      cls: "voice-bmc-link",
      attr: {
        href: BUY_ME_A_COFFEE_URL,
        target: "_blank",
        rel: "noopener"
      }
    });
    const coffeeImg = coffeeLink.createEl("img", {
      cls: "voice-bmc-button",
      attr: { alt: "Buy me a coffee", src: BUY_ME_A_COFFEE_IMAGE_URL }
    });
    coffeeImg.addEventListener("error", () => support.hide());
    const body = contentEl.createDiv({ cls: "voice-whats-new-body" });
    void import_obsidian17.MarkdownRenderer.render(this.app, WHATS_NEW, body, "", this.component);
    new import_obsidian17.Setting(contentEl).addButton(
      (btn) => btn.setButtonText("Open Voice player").setCta().onClick(() => {
        this.onOpenPlayer();
        this.close();
      })
    ).addButton(
      (btn) => btn.setButtonText("Close").onClick(() => this.close())
    );
  }
  onClose() {
    this.contentEl.empty();
  }
};

// src/utils/VoicePlugin.ts
var Voice = class extends import_obsidian18.Plugin {
  async onload() {
    await this.loadSettings();
    this.addSettingTab(new VoiceSettingTab(this.app, this));
    this.markdownHelper = new MarkdownHelper(this.app);
    this.speechProvider = createSpeechProvider(this.settings);
    this.iconEventHandler = new IconEventHandler(
      this,
      this,
      this.speechProvider
    );
    this.textSpeaker = new TextSpeaker(
      this.speechProvider,
      this.markdownHelper,
      this.iconEventHandler,
      this.settings.spellOutAcronyms,
      this.settings.readCodeBlocks,
      this.settings.skipUrls
    );
    this.hotkeySettings = new HotkeySettings(this);
    this.hotkeySettings.initHotkeys();
    this.registerView(
      VIEW_TYPE_VOICE_PLAYER,
      (leaf) => new VoicePlayerView(leaf, this)
    );
    this.addRibbonIcon("audio-lines", "Open Voice player", () => {
      void this.activatePlayerView();
    });
    this.addCommand({
      id: "open-player",
      name: "Open the player.",
      callback: () => void this.activatePlayerView()
    });
    this.addCommand({
      id: "show-whats-new",
      name: "Show what's new.",
      callback: () => this.showWhatsNew()
    });
    this.app.workspace.onLayoutReady(() => {
      void this.placeDefaultPlayerPane();
      this.maybeShowWhatsNew();
    });
  }
  /** Open the "What's New" modal for the current version. */
  showWhatsNew() {
    new WhatsNewModal(
      this.app,
      this.manifest.version,
      this,
      () => void this.activatePlayerView()
    ).open();
  }
  /**
   * Show the "What's New" note once after a fresh install or an update, then
   * remember the version so it is not shown again until the next upgrade.
   */
  maybeShowWhatsNew() {
    const current = this.manifest.version;
    if (!shouldShowWhatsNew(current, this.settings.lastWhatsNewVersion)) {
      return;
    }
    this.settings.lastWhatsNewVersion = current;
    void this.saveSettings();
    this.showWhatsNew();
  }
  /**
   * One-time placement of the player in the right sidebar so it shows up by
   * default (desktop and mobile). The tab is added without revealing it, so it
   * does not steal focus from the user's current pane.
   */
  async placeDefaultPlayerPane() {
    if (this.settings.playerPanePlaced) {
      return;
    }
    this.settings.playerPanePlaced = true;
    await this.saveSettings();
    const { workspace } = this.app;
    if (workspace.getLeavesOfType(VIEW_TYPE_VOICE_PLAYER).length > 0) {
      return;
    }
    const right = workspace.getRightLeaf(false);
    if (!right) {
      return;
    }
    await right.setViewState({ type: VIEW_TYPE_VOICE_PLAYER });
  }
  async speakText(speed) {
    await this.textSpeaker.speakText(speed);
  }
  isMobile() {
    return import_obsidian18.Platform.isMobile;
  }
  onunload() {
    if (this.iconEventHandler) {
      this.iconEventHandler.removeEventListeners();
    }
  }
  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
    if (!this.settings.acronymDefaultMigrated) {
      this.settings.spellOutAcronyms = false;
      this.settings.acronymDefaultMigrated = true;
      await this.saveSettings();
    }
    if (!this.settings.audioFolderMigrated) {
      if (this.settings.audioSaveMode === "custom" && this.settings.lastAudioFolder) {
        this.settings.defaultAudioFolder = this.settings.lastAudioFolder;
      }
      this.settings.audioFolderMigrated = true;
      await this.saveSettings();
    }
  }
  async saveSettings() {
    await this.saveData(this.settings);
  }
  /**
   * Update the active provider's credentials in place (no audio interruption).
   * Called when the user edits AWS or ElevenLabs credentials in settings.
   */
  reinitializeProviderCredentials() {
    this.speechProvider.updateCredentials(this.settings);
  }
  /**
   * Backwards-compatible alias for AWS credential updates.
   */
  reinitializePollyService() {
    this.reinitializeProviderCredentials();
  }
  /**
   * Switch the active TTS provider (e.g. Polly ↔ ElevenLabs). Rewires the UI
   * (status bar, mobile control bar) and orchestration to the new provider.
   */
  reinitializeProvider() {
    this.speechProvider.stopAudio();
    this.speechProvider = createSpeechProvider(this.settings);
    this.iconEventHandler.setProvider(this.speechProvider);
    this.reinitializeTextSpeaker();
  }
  /**
   * Resync any open Voice player panes with the current settings/provider —
   * used after the settings tab changes something the player shows (e.g. a
   * freshly fetched voice catalog), so its voice picker updates immediately.
   */
  refreshVoicePlayerControls() {
    this.app.workspace.getLeavesOfType(VIEW_TYPE_VOICE_PLAYER).forEach((leaf) => {
      if (leaf.view instanceof VoicePlayerView) {
        leaf.view.syncControls();
      }
    });
  }
  reinitializeTextSpeaker() {
    this.textSpeaker = new TextSpeaker(
      this.speechProvider,
      this.markdownHelper,
      this.iconEventHandler,
      this.settings.spellOutAcronyms,
      this.settings.readCodeBlocks,
      this.settings.skipUrls
    );
  }
  /**
   * Persist the chosen voice to the correct settings key for the active
   * provider, apply it to the running provider, and refresh the display.
   */
  async persistActiveVoice(voiceId) {
    if (this.settings.TTS_PROVIDER === "elevenlabs") {
      this.settings.ELEVENLABS_VOICE = voiceId;
    } else if (this.settings.TTS_PROVIDER === "google") {
      this.settings.GOOGLE_VOICE = voiceId;
    } else if (this.settings.TTS_PROVIDER === "azure") {
      this.settings.AZURE_VOICE = voiceId;
    } else if (this.settings.TTS_PROVIDER === "openai") {
      this.settings.OPENAI_VOICE = voiceId;
    } else if (this.settings.TTS_PROVIDER === "openai-compatible") {
      this.settings.OPENAI_COMPAT_VOICE = voiceId;
    } else if (this.settings.TTS_PROVIDER === "minimax") {
      this.settings.MINIMAX_VOICE = voiceId;
    } else {
      this.settings.VOICE = voiceId;
    }
    await this.saveSettings();
    this.speechProvider.setVoice(voiceId);
    this.iconEventHandler.updateVoiceDisplay();
  }
  /**
   * Apply the configured rewind/fast-forward skip intervals to the running
   * provider and refresh the control tooltips. Called when the user changes
   * the interval in settings (no audio interruption).
   */
  updateSkipIntervals() {
    this.speechProvider.setRewindSeconds(this.settings.rewindSeconds);
    this.speechProvider.setForwardSeconds(this.settings.forwardSeconds);
    this.iconEventHandler.updateSkipTooltips();
  }
  /**
   * Switch to the next voice in the active provider's catalog (wraps around).
   * Backs the "Switch to the next voice" command.
   */
  async cycleVoice() {
    const options = this.speechProvider.getVoiceOptions();
    if (options.length === 0) {
      return;
    }
    const currentId = this.speechProvider.getVoice();
    const currentIndex = options.findIndex((v) => v.id === currentId);
    const next = options[(currentIndex + 1) % options.length];
    await this.persistActiveVoice(next.id);
    new import_obsidian18.Notice(`Voice: ${next.label}`);
  }
  /**
   * Open the Voice player and reveal it (right sidebar on desktop, full-screen
   * pane on mobile). Reuses an existing player leaf if one is already open.
   */
  async activatePlayerView() {
    const { workspace } = this.app;
    let leaf = workspace.getLeavesOfType(VIEW_TYPE_VOICE_PLAYER)[0];
    if (!leaf) {
      const right = workspace.getRightLeaf(false);
      if (!right) {
        return;
      }
      leaf = right;
      await leaf.setViewState({
        type: VIEW_TYPE_VOICE_PLAYER,
        active: true
      });
    }
    await workspace.revealLeaf(leaf);
    this.iconEventHandler.hideMobileControlBar();
  }
  getSpeechProvider() {
    return this.speechProvider;
  }
  /**
   * @deprecated Use getSpeechProvider() instead.
   */
  getPollyService() {
    return this.speechProvider;
  }
};

